result-contract.schema:
{
  "status": "completed | partial | blocked | failed",
  "criteria": [
    {
      "id": "AC-1",
      "disposition": "pass | fail | skipped:<reason>",
      "evidence_digest": "sha256:..."
    }
  ],
  "changed_files": ["path/to/file"],
  "unresolved": ["description of any Spec Gap"],
  "verification": {
    "commands_run": ["..."],
    "results": ["pass | fail | skipped:<reason>"]
  }
}
